{
  "title": "The Gilded Ruin Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Massive iron gates hang crooked, rusted hinges groaning as a five-person party approaches through swirling dust under a blood-orange sky.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 2,
      "caption": "Townspeople whisper warnings in the market square.",
      "visual_description": "Huddled figures in tattered cloaks point toward a distant tower, their faces pale and eyes wide with fear.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian", "Town Elder"]
    },
    {
      "scene_number": 3,
      "caption": "The party finds old royal banners torn and faded.",
      "visual_description": "A long hallway lined with fraying banners bearing a lion crest, sunlight slicing through a collapsed ceiling.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 4,
      "caption": "Armored patrols march through the courtyard.",
      "visual_description": "Six helmeted soldiers in black plate mail stomp in unison, their red capes billowing as they pass a cracked fountain.",
      "characters": ["Patrol Soldier", "Patrol Soldier", "Patrol Soldier", "Patrol Soldier", "Patrol Soldier", "Patrol Soldier"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon echo in a tavern.",
      "visual_description": "A smoky tavern interior, a scarred barkeep leans forward, whispering as the party listens at a splintered table.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian", "Barkeep"]
    },
    {
      "scene_number": 6,
      "caption": "The cursed tower looms ahead.",
      "visual_description": "A spiraling black tower covered in glowing violet runes, surrounded by a ring of dead trees under a crescent moon.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 7,
      "caption": "Magic doors block the tower entrance.",
      "visual_description": "Three massive stone doors engraved with shifting symbols, each pulsing with a different color of magical light.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 8,
      "caption": "Mira deciphers the door runes.",
      "visual_description": "Mira kneels, tracing a glowing rune with her finger as the others stand guard, torches flickering.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 9,
      "caption": "The party enters a treasure-laden hall.",
      "visual_description": "Golden coins and jeweled goblets spill from overturned chests, light reflecting off a massive ruby on a pedestal.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 10,
      "caption": "Dorn resists a tempting illusion.",
      "visual_description": "Dorn stares at a shimmering vision of his lost family, sweat beading on his brow as Elara grabs his arm.",
      "characters": ["Dorn", "Elara", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 11,
      "caption": "A spectral guardian challenges them.",
      "visual_description": "A translucent knight in ancient armor rises from the floor, blue fire burning in its eye slits.",
      "characters": ["Spectral Knight", "Elara", "Dorn", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 12,
      "caption": "Finn uses a trick to bypass the guardian.",
      "visual_description": "Finn throws a vial that explodes into smoke, the spectral knight slashing through mist as the party slips past.",
      "characters": ["Finn", "Spectral Knight", "Elara", "Dorn", "Mira", "Guardian"]
    },
    {
      "scene_number": 13,
      "caption": "They reach the prison chamber.",
      "visual_description": "A circular cell with iron bars, a lone figure chained to the center, dim light from a single torch.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian", "Prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "Elara picks the lock on the prisoner's chains.",
      "visual_description": "Close-up of Elara's steady hands working a thin pick into the lock mechanism, chains clinking.",
      "characters": ["Elara", "Prisoner", "Dorn", "Mira", "Finn", "Guardian"]
    },
    {
      "scene_number": 15,
      "caption": "Alarms sound as they flee the tower.",
      "visual_description": "Red light pulses from the tower top, horn blasts echo, and the party runs down a spiral staircase with the freed prisoner.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian", "Prisoner"]
    },
    {
      "scene_number": 16,
      "caption": "Patrols converge on the courtyard.",
      "visual_description": "Soldiers pour from archways, forming a shield wall as the party skids to a halt, trapped.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian", "Prisoner", "Patrol Soldier", "Patrol Soldier", "Patrol Soldier", "Patrol Soldier"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge escape begins under fire.",
      "visual_description": "A narrow stone bridge over a chasm, crossbow bolts whizzing past as the party runs, the prisoner stumbling.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian", "Prisoner"]
    },
    {
      "scene_number": 18,
      "caption": "The party crosses the bridge to safety.",
      "visual_description": "The bridge crumbles behind them as they reach the far side, dust clearing to reveal the ruined city in the distance.",
      "characters": ["Elara", "Dorn", "Mira", "Finn", "Guardian", "Prisoner"]
    }
  ]
}

